ScriptsTab:CreateSection("OP Hubs (Tested Broad Compatibility)")
local function SafeLoad(url, name)
    local success = pcall(function()
        loadstring(game:HttpGet(url, true))() -- true = no cache, helps some executors
    end)
    if success then
        Rayfield:Notify({Title = name .. " ✅ LOADED!", Content = "Enjoy! (Inf Stam, ESP, Auto Gen...)", Duration = 5})
    else
        Rayfield:Notify({Title = name .. " ❌ Failed", Content = "Link dead/patched or executor issue — try another exec", Duration = 6})
    end
end
